<?php
declare(strict_types=1);
if(!$portalReady)return;
$bankReady=setting($db,'provincial_account_number')!=='';
$paymentHistory=new FinancialHistory($db,$ids,$_GET,'payments');$notifications=$paymentHistory->items;
?>
<?php if(canRemit($user)): $ownQuery=$db->prepare("SELECT l.*,COALESCE((SELECT SUM(n.amount) FROM payment_notifications n WHERE n.ledger_id=l.id AND n.status='pending'),0) pending_amount FROM remittance_ledgers l WHERE l.parish_id=? ORDER BY l.period_year DESC,l.period_month DESC,l.id DESC");$ownQuery->execute([(int)$user['hierarchy_id']]);$ownRows=[];$awaiting=false;foreach($ownQuery->fetchAll() as $r){$pending=Money::cents((string)$r['pending_amount']);$awaiting=$awaiting||$pending>0;$remaining=Money::cents($r['provincial_levy_due'])-Money::cents($r['amount_paid'])-$pending;if($remaining>0){$r['available_amount']=Money::decimal($remaining);$ownRows[]=$r;}} ?>
<div class="payment-layout" id="payment-options"><section class="panel form-panel"><div class="section-kicker">01 / MAKE YOUR DEPOSIT</div><h2>Transfer to province</h2><?php if($bankReady): ?><div class="bank-card"><span>PROVINCIAL RECEIVING ACCOUNT</span><h3><?= e(setting($db,'provincial_bank_name')) ?></h3><strong><?= e(setting($db,'provincial_account_number')) ?></strong><p><?= e(setting($db,'provincial_account_name')) ?></p></div><p class="muted small">Use your report reference as the transfer narration.</p><?php else: ?><div class="notice">The provincial receiving account has not been configured. Please contact the treasury before making a transfer.</div><?php endif ?><div class="method-row"><span class="method-icon">⇄</span><div><strong>Manual bank transfer</strong><small><?= $bankReady?'Available · Treasury verification required':'Awaiting bank configuration' ?></small></div><span class="badge <?= $bankReady?'verified':'pending' ?>"><?= $bankReady?'Available':'Pending' ?></span></div><p class="small muted">Automated deposit · PayHub: not connected.</p></section>
<section class="panel form-panel"><div class="section-kicker">02 / NOTIFY THE TREASURY</div><h2>Record your payment</h2><p class="muted small">Treasury confirms payment after checking the bank.</p><?php if($bankReady && $ownRows): ?><form method="post" class="form-grid" enctype="multipart/form-data"><?php hiddenAction('payment_submit') ?><label class="full-width">Offering report<select name="ledger_id" required><option value="">Select an outstanding report</option><?php foreach($ownRows as $r):if(Money::cents($r['provincial_levy_due'])<=Money::cents($r['amount_paid']))continue; ?><option value="<?= (int)$r['id'] ?>"><?= e($r['period_month'].'/'.$r['period_year'].' · '.$r['payment_reference'].' · Due '.Money::display($r['available_amount'])) ?></option><?php endforeach ?></select></label><label>Amount transferred (NGN)<input name="amount" required inputmode="decimal" pattern="[0-9]{1,13}(\.[0-9]{1,2})?"></label><label>Transfer date<input name="transfer_date" type="date" min="2020-01-01" max="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required></label><label class="full-width">Bank transaction reference<input name="transfer_reference" maxlength="100" required></label><?php if(PaymentProof::ready($db) && PaymentProof::supported()): ?><label class="full-width">Payment receipt (optional)<input type="file" name="payment_proof" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP · up to 8 MB. Stored as compressed WebP.</small></label><?php else: ?><p class="small muted full-width">Receipt uploads need admin setup and PHP WebP support.</p><?php endif ?><button class="primary">Submit payment →</button></form><?php else: ?><div class="empty"><h3><?= $awaiting?'Awaiting treasury confirmation':'No unpaid offering' ?></h3><p><?= !$bankReady?'Ask your administrator to configure the provincial bank account.':($awaiting?'Your submitted payment is being reviewed.':'Save a monthly offering to record a payment.') ?></p></div><?php endif ?></section></div><?php endif ?>
<details class="report-history" id="payments-history" data-server-history <?= array_filter(array_keys($_GET),fn($key)=>str_starts_with((string)$key,'payments_'))?'open':'' ?>><summary><?= $treasurer?'Review payments':'Payment history' ?></summary><section class="panel"><div class="panel-heading"><div><h2>Payment notifications</h2><p><?= $treasurer?'Verify against the bank statement.':'Payment status' ?></p></div><span class="chip"><?= $paymentHistory->total ?> payments</span></div><?php $history=$paymentHistory;require __DIR__.'/history-controls.php'; ?><?php if(!$notifications): ?><div class="empty"><span>⇄</span><h3>No payment notifications yet</h3><p>Manual transfer notifications will appear here once submitted by churches.</p></div><?php endif ?><?php foreach($notifications as $n): ?><article class="review-card"><div><span class="badge <?= $n['status']==='approved'?'verified':($n['status']==='rejected'?'rejected':'pending') ?>"><?= e(ucfirst($n['status'])) ?></span><h3><?= e(Money::display($n['amount']).' · '.$n['node_name']) ?></h3><p><?= e($n['payment_reference'].' · Bank ref: '.$n['transfer_reference']) ?></p><small class="muted">Transfer date: <?= e($n['transfer_date']) ?><?= $n['review_note']?' · '.e($n['review_note']):'' ?></small></div><?php if(!empty($n['proof_key']) && ($treasurer || (int)($user['hierarchy_id'] ?? 0)===(int)$n['parish_id'])): $receiptUrl='index.php?download=payment-proof&notification_id='.(int)$n['id']; ?><a class="receipt-link" data-proof-open href="<?= e($receiptUrl) ?>" target="_blank" rel="noopener"><img class="receipt-thumbnail" src="<?= e($receiptUrl.'&thumb=1') ?>" alt="Payment receipt" width="110" height="80" loading="lazy"><span>View receipt</span></a><?php endif ?><?php if($treasurer && $n['status']==='pending'): ?><form method="post" class="review-form"><?php hiddenAction('payment_review') ?><input type="hidden" name="notification_id" value="<?= (int)$n['id'] ?>"><label>Review note<input name="review_note" maxlength="255" placeholder="Optional bank-check notes"></label><label>Transaction PIN<input type="password" name="pin" required pattern="[0-9]{4}" inputmode="numeric" autocomplete="off"></label><div class="review-actions"><button name="decision" value="approved" class="primary">Approve deposit</button><button name="decision" value="rejected" class="secondary">Reject</button></div></form><?php endif ?></article><?php endforeach ?><?php $history=$paymentHistory;require __DIR__.'/history-pagination.php'; ?></section></details>
<dialog id="receipt-dialog" class="receipt-dialog" aria-labelledby="receipt-dialog-title"><div class="receipt-dialog-heading"><h2 id="receipt-dialog-title">Payment receipt</h2><button type="button" class="secondary" data-proof-close aria-label="Close receipt preview">×</button></div><p data-proof-error role="status" hidden>Receipt could not be loaded. Reopen it or sign in again.</p><img data-proof-image alt="Uploaded payment receipt"></dialog>
